!function(){"use strict";var e=window.ACADEMY_DATA=window.ACADEMY_DATA||{buildings:[],modules:[]};e.buildings.push({id:"network",icon:"🌐",title:"نیٹ ورک ٹاور",en:"Network & Systems Tower",color:"#3fb950",tracks:["noori","mano"],blurb:"IP، subnetting، DNS، DHCP، routing، TCP/UDP، HTTP(S)، Linux، Windows اور troubleshooting۔"},{id:"cyber",icon:"🛡️",title:"سائبر قلعہ",en:"Cyber Fortress",color:"#ff8a3d",tracks:["noori","mano"],blurb:"سیکیورٹی اصول، شناخت، کرپٹوگرافی، ویب سیکیورٹی، WAF، فائر وال، SOC، انسیڈنٹ رسپانس، کلاؤڈ اور رسک۔"});var i='<p class="ac-warn">⚖️ <b>اجازت کا اصول:</b> سیکیورٹی ٹیسٹ صرف اپنی چیزوں پر، یا تحریری اجازت (written authorization) کے ساتھ، یا اس اکیڈمی کی بند لیب میں۔ کسی اور کے سسٹم کو بغیر اجازت جانچنا قانوناً جرم ہے (پاکستان: PECA 2016)۔</p>';e.modules.push({id:"n1-ip",building:"network",order:1,icon:"📮",tracks:["noori","mano"],skill:"networking",skillName:"نیٹ ورک کی بنیاد",title:"IP ایڈریس اور نیٹ ورک کی بنیاد",en:"IP Addresses & Networks",minutes:20,objective:"IPv4 کے چار حصے، private بمقابلہ public IP، router اور packet کا کردار سمجھنا۔",lessons:[{t:"IP ایڈریس",h:"<p>ہر ڈیوائس کا ایک پتہ ہوتا ہے: <code>192.168.1.10</code>۔ IPv4 میں 4 حصے (octets) ہیں، ہر حصہ 0 سے 255 (8 bits)۔</p><ul><li><b>Private IP</b> گھر/دفتر کے اندر: <code>10.x.x.x</code>، <code>172.16–31.x.x</code>، <code>192.168.x.x</code>۔</li><li><b>Public IP</b> انٹرنیٹ پر نظر آنے والا پتہ (router کا)۔</li><li><b>Router</b> packets کو صحیح نیٹ ورک تک پہنچاتا ہے؛ <b>switch</b> ایک ہی نیٹ ورک کے اندر۔</li></ul>"}],mano:{lessons:[{t:"کمپیوٹر کا گھر کا پتہ",h:"<p>جیسے خط کو گھر کا پتہ چاہیے، ویسے ہی ہر کمپیوٹر کا ایک <b>IP پتہ</b> ہے۔ <b>Router</b> ڈاکیا ہے جو پیغام پہنچاتا ہے 📮۔</p>"}]},example:{t:"مثال",h:"<p>نوری کا لیپ ٹاپ <code>192.168.1.23</code> (private)۔ گھر کا router انٹرنیٹ پر <code>203.0.113.7</code> (public) کے نام سے بات کرتا ہے۔</p>"},activity:{type:"classify",title:"Private یا Public؟",stages:[{name:"Beginner",buckets:["Private (اندر)","Public (انٹرنیٹ)"],items:[["192.168.1.5",0],["10.0.0.8",0],["8.8.8.8",1],["172.16.4.2",0],["203.0.113.50",1]]},{name:"Intermediate",buckets:["درست IPv4","غلط"],items:[["192.168.1.256",1],["10.10.10.10",0],["300.1.1.1",1],["172.20.0.1",0],["1.2.3",1],["0.0.0.0",0]]}]},activityMano:{type:"order",title:"پیغام کا سفر",stages:[{name:"Beginner",items:["مانو پیغام لکھتی ہے","کمپیوٹر پیکٹ بناتا ہے","Router پتہ دیکھتا ہے","دوست کو پیغام ملتا ہے"]}]},quizMano:[{q:"نیٹ ورک کیا ہے؟",o:["آپس میں جُڑے کمپیوٹر جو بات کرتے ہیں","ایک گیم"],a:0,e:"نیٹ ورک = کمپیوٹر دوست جو آپس میں جُڑے ہیں۔"},{q:"ہر کمپیوٹر کا نیٹ ورک میں کیا ہوتا ہے؟",o:["اپنا پتا (IP)","اپنا رنگ"],a:0,e:"جیسے گھر کا پتا ہوتا ہے، ویسے کمپیوٹر کا IP پتا ہوتا ہے۔"}],quiz:[{q:"IPv4 کے ہر حصے کی سب سے بڑی قیمت؟",o:["255","999","100"],a:0,e:"8 bits = 0 تا 255۔"},{q:"192.168.0.10 کیسا IP ہے؟",o:["Private","Public"],a:0,e:"192.168.x.x private رینج ہے۔"}],reflect:"Router کا کام اپنے الفاظ میں لکھیں۔",concepts:[{k:["ip","ip address","آئی پی","ip adress","ipv4"],t:"IP address",noori:"IP address نیٹ ورک پر ڈیوائس کا پتہ ہے۔ IPv4 میں چار octets (0–255)۔ Private رینجز: 10/8، 172.16/12، 192.168/16۔",mano:"IP کمپیوٹر کے گھر کا پتہ ہے۔",harmi:"ہر کمپیوٹر کا ایک گھر کا پتہ ہوتا ہے 🏠"},{k:["router","راؤٹر","switch"],t:"Router",noori:"Router مختلف نیٹ ورکس کے درمیان packets کو راستہ دکھاتا ہے؛ switch ایک نیٹ ورک کے اندر ڈیوائسز جوڑتا ہے۔",mano:"Router ڈاکیا ہے جو پیغام صحیح جگہ پہنچاتا ہے۔"},{k:["packet","پیکٹ"],t:"Packet",noori:"ڈیٹا چھوٹے ٹکڑوں (packets) میں جاتا ہے، ہر ایک پر source اور destination IP لکھا ہوتا ہے۔"}]},{id:"n2-subnet",building:"network",order:2,icon:"🧮",tracks:["noori"],skill:"subnetting",skillName:"Subnetting",title:"Subnetting",en:"Subnetting & CIDR",minutes:35,objective:"CIDR (/24, /26…) سے network address، broadcast address اور قابل استعمال hosts کا حساب لگانا۔",lessons:[{t:"CIDR",h:"<p><code>192.168.1.0/24</code> میں /24 کا مطلب: پہلے 24 bits نیٹ ورک، باقی 8 bits hosts۔</p><ul><li>کل پتے = 2<sup>(32−prefix)</sup></li><li>قابل استعمال hosts = کل − 2 (network اور broadcast)</li><li><b>Block size</b> (آخری اہم octet میں) = 256 − mask کا وہ octet</li></ul><p>مثال /26: mask 255.255.255.192، block size 64 → نیٹ ورکس 0, 64, 128, 192۔</p>"},{t:"طریقہ",h:"<ol><li>prefix سے block size نکالیں۔</li><li>IP کو block size کے حساب سے نیچے گول کریں → network address۔</li><li>network + block − 1 → broadcast۔</li><li>hosts = block − 2 (اگر block پورا آخری octet میں ہو)۔</li></ol><p>مثال: <code>10.0.0.77/27</code> → block 32 → network 10.0.0.64، broadcast 10.0.0.95، hosts 30۔</p>"}],example:{t:"مثال",h:"<p><code>172.16.5.130/25</code> → block 128 → network 172.16.5.128، broadcast 172.16.5.255، 126 hosts۔</p>"},activity:{type:"subnet",title:"Subnet کیلکولیٹر چیلنج (ہر بار نئے سوال)",stages:[{name:"Beginner",prefixes:[24],ask:["network","hosts"],count:3},{name:"Intermediate",prefixes:[25,26,27],ask:["network","broadcast","hosts"],count:3},{name:"Advanced",prefixes:[20,21,22,23,28,29],ask:["network","broadcast","hosts"],count:3}]},quiz:[{q:"/26 میں کل پتے؟",o:["64","62","256"],a:0,e:"2^(32−26)=64؛ قابل استعمال 62۔"},{q:"/30 میں قابل استعمال hosts؟",o:["2","4","0"],a:0,e:"4 − 2 = 2 (point-to-point links کے لیے)۔"}],reflect:"Subnetting سے نیٹ ورک محفوظ اور منظم کیسے ہوتا ہے؟",concepts:[{k:["subnet","subnetting","cidr","سب نیٹ","subneting","mask"],t:"Subnetting",noori:"Subnetting نیٹ ورک کو چھوٹے حصوں میں بانٹتا ہے۔ کل پتے = 2^(32−prefix)، hosts = کل − 2، block size = 256 − mask octet۔",steps:["prefix سے block size نکالیں","IP کو block پر نیچے گول کریں = network","network + block − 1 = broadcast","hosts = block − 2"],ex:"10.0.0.77/27 → network 10.0.0.64، broadcast 10.0.0.95، 30 hosts"}]},{id:"n3-dns-dhcp",building:"network",order:3,icon:"📒",tracks:["noori","mano"],skill:"dns-dhcp-routing",skillName:"DNS، DHCP اور Routing",title:"DNS، DHCP اور Routing",en:"DNS, DHCP & Routing",minutes:25,objective:"DNS نام کو IP میں کیسے بدلتا ہے، DHCP پتہ کیسے دیتا ہے، اور default gateway کیا ہے۔",lessons:[{t:"DNS",h:'<p><b>DNS</b> انٹرنیٹ کی فون بک ہے: <code>example.com</code> → <code>93.184.215.14</code>۔ ترتیب: براؤزر cache → OS cache → DNS resolver → root → .com → example.com کا authoritative server۔</p><p class="ac-warn">جعلی DNS جواب (DNS spoofing) آپ کو جعلی سائٹ پر لے جا سکتا ہے، اسی لیے HTTPS سرٹیفکیٹ کی جانچ اہم ہے۔</p>'},{t:"DHCP اور Routing",h:"<p><b>DHCP</b> نئی ڈیوائس کو خود IP، subnet mask، gateway اور DNS دیتا ہے (DORA: Discover, Offer, Request, Acknowledge)۔</p><p><b>Default gateway</b> (عموماً router) وہ دروازہ ہے جہاں سے باہر کے نیٹ ورک کو packets جاتے ہیں۔ Router اپنی <b>routing table</b> سے اگلا قدم (next hop) چنتا ہے۔</p>"}],mano:{lessons:[{t:"نام سے نمبر",h:"<p>ہم <code>google.com</code> لکھتے ہیں، کمپیوٹر کو نمبر چاہیے۔ <b>DNS</b> فون بک کی طرح نام کو نمبر میں بدلتا ہے 📒۔</p>"}]},example:{t:"مثال",h:"<p>نوری نے لیپ ٹاپ WiFi سے جوڑا → DHCP نے 192.168.1.23 دیا → اس نے cyberheroes.example لکھا → DNS نے IP بتایا → gateway سے packet باہر گیا۔</p>"},activity:{type:"order",title:"ترتیب بنائیں",stages:[{name:"Beginner",items:["براؤزر میں نام لکھا","DNS سے IP پوچھا","IP ملا","سرور سے صفحہ مانگا"]},{name:"Intermediate",items:["DHCP Discover","DHCP Offer","DHCP Request","DHCP Acknowledge"]},{name:"Advanced",items:["Browser cache","OS cache","Recursive resolver","Root server","TLD (.com) server","Authoritative server"]}]},quizMano:[{q:"DNS کیا کرتا ہے؟",o:["ویب سائٹ کا نام نمبر والے پتے میں بدلتا ہے","گانا بجاتا ہے"],a:0,e:"DNS فون بک کی طرح ہے: نام سے نمبر ڈھونڈتا ہے۔"},{q:"ہم ویب سائٹ کیسے کھولتے ہیں؟",o:["اس کا نام لکھ کر","کمپیوٹر ہلا کر"],a:0,e:"ہم نام لکھتے ہیں، DNS باقی کام کرتا ہے۔"}],quiz:[{q:"DNS کا کام؟",o:["نام کو IP میں بدلنا","IP خود دینا","وائرس روکنا"],a:0,e:"DNS name resolution کرتا ہے۔"},{q:"نئے لیپ ٹاپ کو IP کون دیتا ہے؟",o:["DHCP","DNS","HTTP"],a:0,e:"DHCP خودکار IP دیتا ہے۔"},{q:"Default gateway عموماً کیا ہوتا ہے؟",o:["Router","Printer"],a:0,e:"باہر جانے کا دروازہ router ہے۔"}],reflect:"اگر DNS کام نہ کرے تو کیا ہوگا؟",concepts:[{k:["dns","ڈی این ایس","domain name","name server"],t:"DNS",noori:"DNS ڈومین نام کو IP میں بدلتا ہے: cache → resolver → root → TLD → authoritative۔",mano:"DNS انٹرنیٹ کی فون بک ہے۔",ex:"example.com → 93.184.215.14"},{k:["dhcp","ڈی ایچ سی پی"],t:"DHCP",noori:"DHCP خود IP، mask، gateway اور DNS دیتا ہے: Discover, Offer, Request, Acknowledge۔"},{k:["routing","gateway","default gateway","روٹنگ"],t:"Routing",noori:"Routing packet کا اگلا قدم چنتی ہے؛ default gateway باہر کے نیٹ ورک کا دروازہ ہے۔"}]},{id:"n4-tcp-udp",building:"network",order:4,icon:"🚚",tracks:["noori"],skill:"protocols",skillName:"TCP/UDP اور پروٹوکولز",title:"TCP، UDP اور عام پورٹس",en:"TCP, UDP & Common Protocols",minutes:25,objective:"TCP اور UDP کا فرق، three-way handshake، اور عام پورٹس (22, 53, 80, 443, 3389)۔",lessons:[{t:"TCP بمقابلہ UDP",h:"<p><b>TCP</b>: قابل اعتماد، ترتیب سے، پہنچنے کی تصدیق — ویب، ای میل، فائلیں۔ کنکشن سے پہلے <b>SYN → SYN-ACK → ACK</b>۔</p><p><b>UDP</b>: تیز، بغیر تصدیق — ویڈیو کال، گیمز، DNS سوالات۔</p>"},{t:"پورٹس",h:"<p>IP گھر کا پتہ ہے تو <b>port</b> کمرہ نمبر:</p><ul><li>22 SSH (محفوظ ریموٹ لاگ ان)</li><li>53 DNS</li><li>80 HTTP، 443 HTTPS</li><li>25/587 ای میل بھیجنا</li><li>3389 RDP (Windows ریموٹ ڈیسک ٹاپ — انٹرنیٹ پر کھلا چھوڑنا خطرناک)</li></ul>"}],example:{t:"مثال",h:"<p>ویڈیو کال میں ایک فریم کھو جائے تو دوبارہ بھیجنے کے بجائے آگے بڑھنا بہتر ہے — اس لیے UDP۔ بینک ٹرانسفر میں ہر byte چاہیے — TCP۔</p>"},activity:{type:"classify",title:"TCP یا UDP؟ اور پورٹس",stages:[{name:"Beginner",buckets:["TCP","UDP"],items:[["ویب صفحہ (HTTPS)",0],["آن لائن گیم کی تیز حرکت",1],["ای میل",0],["ویڈیو کال",1],["فائل ڈاؤن لوڈ",0]]},{name:"Intermediate",buckets:["22","53","443","3389"],items:[["SSH",0],["DNS",1],["HTTPS",2],["RDP",3]]},{name:"Advanced",buckets:["انٹرنیٹ پر کھلا ہونا عام","عام طور پر صرف VPN/اندر"],items:[["443 ویب سائٹ",0],["3389 RDP",1],["22 SSH (admin)",1],["80→443 redirect",0],["3306 MySQL ڈیٹا بیس",1]]}]},quiz:[{q:"TCP handshake کی ترتیب؟",o:["SYN, SYN-ACK, ACK","ACK, SYN, FIN"],a:0,e:"Three-way handshake۔"},{q:"RDP (3389) کو انٹرنیٹ پر کیوں نہ کھولیں؟",o:["اس پر brute-force اور exploits کے حملے عام ہیں","یہ سست ہے"],a:0,e:"ریموٹ رسائی VPN/MFA کے پیچھے رکھیں۔"}],reflect:"آپ کی پسندیدہ ایپ کون سا پروٹوکول استعمال کرتی ہوگی؟",concepts:[{k:["tcp","udp","ٹی سی پی","handshake"],t:"TCP & UDP",noori:"TCP قابل اعتماد اور ترتیب وار ہے (SYN, SYN-ACK, ACK)؛ UDP تیز مگر بغیر تصدیق۔",mano:"TCP رجسٹرڈ خط کی طرح، UDP جلدی والا پیغام۔"},{k:["port","پورٹ","ports","443","22","3389"],t:"Ports",noori:"Port سروس کا کمرہ نمبر ہے: 22 SSH، 53 DNS، 80 HTTP، 443 HTTPS، 3389 RDP۔ غیر ضروری پورٹس بند رکھیں۔"}]},{id:"n5-http",building:"network",order:5,icon:"🔒",tracks:["noori"],skill:"http",skillName:"HTTP اور HTTPS",title:"HTTP اور HTTPS",en:"HTTP & HTTPS",minutes:25,objective:"request/response، methods، status codes اور HTTPS/TLS کیا تحفظ دیتا ہے۔",lessons:[{t:"Request اور Response",h:"<pre>GET /index.html HTTP/1.1\nHost: cyberheroes.example\n\nHTTP/1.1 200 OK\nContent-Type: text/html</pre><p><b>Methods</b>: GET (مانگنا)، POST (بھیجنا)، PUT/PATCH (بدلنا)، DELETE۔<br><b>Status</b>: 200 ٹھیک، 301/302 دوسری جگہ، 401 لاگ ان چاہیے، 403 اجازت نہیں، 404 نہیں ملا، 500 سرور کی خرابی۔</p>"},{t:"HTTPS",h:'<p>HTTPS = HTTP + <b>TLS</b>۔ TLS راستے میں ڈیٹا کو encrypt کرتا ہے اور certificate سے سرور کی پہچان ثابت کرتا ہے۔</p><p class="ac-warn">تالے 🔒 کا مطلب صرف "راستہ محفوظ" ہے، یہ نہیں کہ سائٹ ایماندار ہے۔ فشنگ سائٹس بھی HTTPS رکھ سکتی ہیں۔</p>'}],example:{t:"مثال",h:"<p>لاگ ان کے بغیر <code>/admin</code> کھولا → <b>401</b>۔ لاگ ان کیا مگر admin نہیں → <b>403</b>۔</p>"},activity:{type:"classify",title:"Status code پہچانیں",stages:[{name:"Beginner",buckets:["200","404","500"],items:[["صفحہ مل گیا",0],["صفحہ موجود نہیں",1],["سرور کریش",2]]},{name:"Intermediate",buckets:["401","403","301"],items:[["پہلے لاگ ان کریں",0],["لاگ ان ہے مگر اجازت نہیں",1],["صفحہ نئی جگہ منتقل",2]]},{name:"Advanced",buckets:["HTTPS تحفظ دیتا ہے","HTTPS تحفظ نہیں دیتا"],items:[["WiFi پر جاسوسی سے",0],["راستے میں ڈیٹا بدلنے سے",0],["جعلی مگر HTTPS والی فشنگ سائٹ سے",1],["کمزور پاس ورڈ سے",1],["سرور کی پہچان ثابت کرنے میں",0]]}]},quiz:[{q:"403 کا مطلب؟",o:["اجازت نہیں","نہیں ملا","ٹھیک"],a:0,e:"Forbidden۔"},{q:"🔒 کا مطلب سائٹ قابل بھروسہ ہے؟",o:["ہاں ہمیشہ","نہیں، صرف کنکشن encrypted ہے"],a:1,e:"ڈومین کا نام ضرور جانچیں۔"}],reflect:"HTTPS کیا حفاظت کرتا ہے اور کیا نہیں؟",concepts:[{k:["http","https","ایچ ٹی ٹی پی","tls","ssl"],t:"HTTP/HTTPS",noori:"HTTP ویب کی درخواست/جواب کی زبان ہے۔ HTTPS اس میں TLS encryption اور certificate سے سرور کی پہچان شامل کرتا ہے، مگر سائٹ کی ایمانداری کی ضمانت نہیں۔",mano:"HTTPS والی ویب سائٹ پر بات راستے میں چھپی رہتی ہے 🔒۔"},{k:["status code","404","403","401","500","200"],t:"HTTP status codes",noori:"200 OK، 301 منتقل، 401 لاگ ان چاہیے، 403 اجازت نہیں، 404 نہیں ملا، 500 سرور خرابی۔"}]},{id:"n6-linux",building:"network",order:6,icon:"🐧",tracks:["noori"],skill:"linux",skillName:"Linux",title:"Linux کمانڈ لائن",en:"Linux Command Line",minutes:30,objective:"grep، chmod، ls -l، whoami، sudo کا محفوظ استعمال اور permissions پڑھنا۔",lessons:[{t:"مفید کمانڈز",h:'<ul><li><code>whoami</code> — کون سا صارف ہوں</li><li><code>ls -l</code> — تفصیل اور permissions</li><li><code>grep FAILED auth.log</code> — فائل میں لفظ ڈھونڈیں</li><li><code>chmod 600 secret.txt</code> — صرف مالک پڑھ/لکھ سکے</li><li><code>sudo</code> — admin کے طور پر؛ صرف ضرورت پر</li></ul><p>Permissions: <code>-rw-r--r--</code> = مالک پڑھ/لکھ، گروپ اور باقی صرف پڑھ۔ r=4, w=2, x=1 → 644۔</p><p class="ac-warn">کبھی بھی انٹرنیٹ سے کاپی کی ہوئی کمانڈ (خاص طور پر <code>sudo</code> یا <code>rm -rf</code>) سمجھے بغیر نہ چلائیں۔</p>'}],example:{t:"مثال",h:"<pre>$ grep FAILED auth.log | wc -l\n7</pre><p>سات ناکام لاگ ان — SOC تجزیہ کار کا پہلا اشارہ۔</p>"},activity:{type:"terminal",title:"Linux مشن (Simulation)",os:"linux",fs:{"/home/noori":["auth.log","secret.txt","scripts/"],"/home/noori/scripts":["backup.sh"]},files:{"/home/noori/auth.log":"10:01 OK noori 192.168.1.10\n10:02 FAILED admin 45.13.0.9\n10:02 FAILED admin 45.13.0.9\n10:03 FAILED admin 45.13.0.9\n10:04 OK mano 192.168.1.11\n10:05 FAILED root 45.13.0.9","/home/noori/secret.txt":"Wi-Fi guest password changes weekly.","/home/noori/scripts/backup.sh":"echo backup"},perms:{"/home/noori/secret.txt":"644","/home/noori/scripts/backup.sh":"644"},stages:[{name:"Beginner",tasks:[{say:"معلوم کریں آپ کون سا صارف ہیں (whoami)۔",expect:{cmd:"whoami"}},{say:"ls -l سے permissions دیکھیں۔",expect:{cmd:"ls",flag:"-l"}}]},{name:"Intermediate",tasks:[{say:"auth.log میں FAILED والی لائنیں grep سے ڈھونڈیں۔",expect:{cmd:"grep",arg:"FAILED"}},{say:"حملہ آور کا IP جواب کے طور پر لکھیں: answer 45.13.0.9",expect:{answer:"45.13.0.9"}}]},{name:"Advanced",tasks:[{say:"secret.txt کو صرف مالک کے لیے کریں: chmod 600 secret.txt",expect:{perm:["/home/noori/secret.txt","600"]}},{say:"backup.sh کو مالک کے لیے چلنے کے قابل بنائیں (700 یا 744)۔",expect:{permAny:["/home/noori/scripts/backup.sh",["700","744","755"]]}}]}]},quiz:[{q:"chmod 600 کا مطلب؟",o:["صرف مالک پڑھ/لکھ","سب پڑھ/لکھ","کوئی نہیں"],a:0,e:"6=rw مالک کے لیے، 0 باقی کے لیے۔"},{q:"grep کیا کرتا ہے؟",o:["متن تلاش","فائل مٹانا"],a:0,e:"grep pattern والی لائنیں دکھاتا ہے۔"}],reflect:"Least privilege کا خیال آپ کمپیوٹر پر کیسے لاگو کریں گی؟",concepts:[{k:["linux","لینکس","ubuntu","kali","bash"],t:"Linux",noori:"Linux ایک open-source OS ہے جو سرورز پر بہت عام ہے۔ کمانڈز: whoami، ls -l، cd، cat، grep، chmod، sudo۔"},{k:["chmod","permission","permissions","پرمیشن"],t:"Permissions",noori:"Linux permissions: r=4, w=2, x=1 مالک/گروپ/باقی کے لیے۔ 600 = صرف مالک پڑھ/لکھ۔"},{k:["grep"],t:"grep",noori:"grep فائل میں pattern ڈھونڈتا ہے: grep FAILED auth.log"}]},{id:"n7-windows",building:"network",order:7,icon:"🪟",tracks:["noori"],skill:"windows-admin",skillName:"Windows ایڈمنسٹریشن",title:"Windows ایڈمنسٹریشن کی بنیاد",en:"Windows Administration Basics",minutes:25,objective:"Task Manager، Event Viewer، صارف اکاؤنٹس، Windows Security اور ipconfig/whoami کا استعمال۔",lessons:[{t:"اہم ٹولز",h:"<ul><li><b>Task Manager</b> (Ctrl+Shift+Esc) — کون سا پروگرام CPU/RAM کھا رہا ہے</li><li><b>Event Viewer</b> — سسٹم لاگز؛ Security log میں 4625 = ناکام لاگ ان، 4624 = کامیاب</li><li><b>Windows Security</b> — Defender antivirus، firewall، updates</li><li><b>Standard user</b> بمقابلہ <b>Administrator</b> — روزمرہ کام standard اکاؤنٹ سے کریں</li><li><code>ipconfig</code>، <code>whoami</code>، <code>ping</code>، <code>netstat -ano</code></li></ul>"}],example:{t:"مثال",h:"<p>لیپ ٹاپ سست ہے → Task Manager → ایک نامعلوم پروسیس 90% CPU → بڑوں کو بتائیں، Defender اسکین چلائیں۔</p>"},activity:{type:"terminal",title:"Windows کمانڈ پرامپٹ (Simulation)",os:"windows",fs:{"C:\\Users\\Noori":["Documents\\","Downloads\\"],"C:\\Users\\Noori\\Downloads":["invoice.pdf.exe","notes.txt"]},files:{"C:\\Users\\Noori\\Downloads\\notes.txt":"Remember: update Windows every week."},stages:[{name:"Beginner",tasks:[{say:"whoami چلائیں۔",expect:{cmd:"whoami"}},{say:"ipconfig سے اپنا IP دیکھیں۔",expect:{cmd:"ipconfig"}}]},{name:"Intermediate",tasks:[{say:"Downloads میں جائیں اور dir چلائیں۔",expect:{cmd:"dir",cwd:"C:\\Users\\Noori\\Downloads"}},{say:"مشکوک فائل کا نام لکھیں: answer invoice.pdf.exe",expect:{answer:"invoice.pdf.exe"}}]},{name:"Advanced",tasks:[{say:"4625 event کس چیز کا ہے؟ answer failed یا answer success",expect:{answer:"failed"}}]}]},quiz:[{q:"روزمرہ کام کس اکاؤنٹ سے؟",o:["Standard user","Administrator"],a:0,e:"Least privilege: admin صرف ضرورت پر۔"},{q:"Event ID 4625؟",o:["ناکام لاگ ان","کامیاب لاگ ان"],a:0,e:"4625 failed logon، 4624 successful۔"}],reflect:"آپ اپنے Windows لیپ ٹاپ کو محفوظ رکھنے کے لیے کون سی 3 عادتیں اپنائیں گی؟",concepts:[{k:["windows","ونڈوز","event viewer","task manager","defender"],t:"Windows administration",noori:"Task Manager پروسیس دکھاتا ہے، Event Viewer لاگز (4624 کامیاب، 4625 ناکام لاگ ان)، Windows Security میں Defender اور firewall۔ روزانہ standard اکاؤنٹ استعمال کریں۔"}]},{id:"n8-troubleshoot",building:"network",order:8,icon:"🧰",tracks:["noori"],skill:"net-troubleshooting",skillName:"نیٹ ورک ٹربل شوٹنگ",title:"نیٹ ورک ٹربل شوٹنگ",en:"Network Troubleshooting",minutes:20,objective:"نیچے سے اوپر (cable → IP → gateway → DNS → app) منطقی ترتیب سے خرابی ڈھونڈنا۔",lessons:[{t:"نیچے سے اوپر",h:"<ol><li>کیا WiFi/cable جڑی ہے؟</li><li><code>ipconfig</code>: کیا درست IP ملا؟ (169.254.x.x = DHCP سے IP نہیں ملا)</li><li><code>ping</code> gateway — router تک پہنچ؟</li><li><code>ping 8.8.8.8</code> — انٹرنیٹ تک پہنچ؟</li><li><code>nslookup example.com</code> — DNS کام کر رہا ہے؟</li><li>براؤزر/ایپ کی سیٹنگز۔</li></ol><p>ہر قدم نتیجہ دیتا ہے کہ خرابی کس تہہ (layer) میں ہے۔</p>"}],example:{t:"مثال",h:"<p>ping 8.8.8.8 کامیاب مگر ping google.com ناکام → مسئلہ DNS میں ہے۔</p>"},activity:{type:"order",title:"ٹربل شوٹنگ کی ترتیب",stages:[{name:"Beginner",items:["کیبل/WiFi چیک","IP چیک (ipconfig)","Gateway کو ping","انٹرنیٹ IP کو ping","DNS چیک"]},{name:"Intermediate",items:["مسئلہ واضح لکھیں","حالیہ تبدیلی معلوم کریں","اندازہ بنائیں","ایک ٹیسٹ کریں","حل لاگو کریں","تصدیق اور نوٹ"]}]},quiz:[{q:"169.254.x.x IP کا مطلب؟",o:["DHCP سے IP نہیں ملا","سب ٹھیک ہے"],a:0,e:"APIPA پتہ — DHCP ناکام۔"},{q:"IP ping ہوتا ہے مگر نام نہیں — مسئلہ؟",o:["DNS","کیبل"],a:0,e:"نام سے IP کی تبدیلی ناکام ہے۔"}],reflect:"آخری بار انٹرنیٹ بند ہوا تو کیا وجہ تھی؟",concepts:[{k:["troubleshoot","troubleshooting","internet nahi","net nahi chal","ping","ٹربل شوٹنگ","nslookup"],t:"Network troubleshooting",noori:"نیچے سے اوپر جانچیں: کنکشن → IP → gateway ping → 8.8.8.8 ping → DNS (nslookup) → ایپ۔",steps:["WiFi/cable","ipconfig","ping gateway","ping 8.8.8.8","nslookup"]}]},{id:"s1-principles",building:"cyber",order:1,icon:"🏰",tracks:["noori","mano"],skill:"security-principles",skillName:"سیکیورٹی اصول اور تھریٹ ماڈلنگ",title:"سیکیورٹی اصول اور تھریٹ ماڈلنگ",en:"Security Principles & Threat Modelling",minutes:25,objective:"CIA triad، least privilege، defense in depth، اور STRIDE سے خطرات کی فہرست بنانا۔",lessons:[{t:"CIA اور اصول",h:"<p><b>Confidentiality</b> راز راز رہے، <b>Integrity</b> ڈیٹا درست رہے، <b>Availability</b> سروس چلتی رہے۔</p><ul><li><b>Least privilege</b>: صرف اتنی اجازت جتنی ضرورت۔</li><li><b>Defense in depth</b>: کئی تہیں — ایک ناکام ہو تو دوسری بچائے۔</li><li><b>Secure by default</b>: پہلے سے محفوظ سیٹنگ۔</li></ul>"},{t:"STRIDE",h:'<p>Threat modelling = "کیا غلط ہو سکتا ہے؟" پہلے سوچنا۔ STRIDE:</p><ul><li><b>S</b>poofing — جعلی شناخت</li><li><b>T</b>ampering — ڈیٹا میں چھیڑ چھاڑ</li><li><b>R</b>epudiation — "میں نے نہیں کیا" (لاگز نہیں)</li><li><b>I</b>nformation disclosure — راز لیک</li><li><b>D</b>enial of service — سروس بند</li><li><b>E</b>levation of privilege — عام صارف admin بن جائے</li></ul>'}],mano:{lessons:[{t:"تین حفاظتی وعدے",h:"<p>🔐 راز راز رہے۔ ✅ چیز درست رہے۔ 🟢 چیز کام کرتی رہے۔ یہ <b>CIA</b> ہیں!</p>"}]},example:{t:"مثال: اسکول کی ہوم ورک ایپ",h:"<p>کوئی ٹیچر بن کر لاگ ان (S) → MFA۔ نمبرز بدلنا (T) → اجازتیں اور لاگز۔ سب طلبہ کے نمبر لیک (I) → access control۔</p>"},activity:{type:"classify",title:"STRIDE پہچانیں",stages:[{name:"Beginner",buckets:["Confidentiality","Integrity","Availability"],items:[["پاس ورڈ لیک",0],["نمبرز میں چھیڑ چھاڑ",1],["ویب سائٹ بند",2],["ڈائری کوئی اور پڑھ لے",0],["بینک بیلنس غلط بدلا گیا",1]]},{name:"Advanced",buckets:["Spoofing","Tampering","Repudiation","Info disclosure","DoS","Elevation"],items:[["کسی اور کی ای میل سے لاگ ان",0],["URL میں price=1 کر دیا",1],["لاگز نہ ہونے سے ثابت نہ ہو سکا",2],["API نے سب صارفین کے فون نمبر دکھا دیے",3],["لاکھوں درخواستوں سے سرور بند",4],["عام صارف نے admin پینل کھول لیا",5]]}]},quizMano:[{q:"ڈائری کا راز راز رہے — یہ کون سا وعدہ ہے؟",o:["C (راز)","I (سچائی)","A (ملنا)"],a:0,e:"C = Confidentiality: راز صرف ان کے لیے جنہیں اجازت ہو۔"},{q:"کوئی چپکے سے آپ کا ہوم ورک بدل دے — کون سا وعدہ ٹوٹا؟",o:["I (ڈیٹا صحیح رہے)","A (ملنا)"],a:0,e:"I = Integrity: ڈیٹا بغیر اجازت نہ بدلے۔"}],quiz:[{q:"Least privilege کا مطلب؟",o:["سب کو admin","ضرورت جتنی اجازت"],a:1,e:"کم اجازت = کم نقصان۔"},{q:"Defense in depth؟",o:["حفاظت کی کئی تہیں","صرف ایک مضبوط تالا"],a:0,e:"کئی کنٹرول مل کر بچاتے ہیں۔"}],reflect:"اپنے گھر کے WiFi کا threat model: کیا غلط ہو سکتا ہے؟",concepts:[{k:["cia","cia triad","confidentiality","integrity","availability"],t:"CIA triad",noori:"Confidentiality (راز)، Integrity (درستگی)، Availability (دستیابی) سیکیورٹی کے تین ستون ہیں۔",mano:"راز راز رہے، چیز درست رہے، اور کام کرتی رہے۔"},{k:["threat model","threat modelling","threat modeling","stride","تھریٹ"],t:"Threat modelling",noori:"Threat modelling: سسٹم بنائیں (diagram)، STRIDE سے خطرات سوچیں، ہر خطرے کا کنٹرول لکھیں، ترجیح دیں۔"},{k:["cyber security","cybersecurity","cyber secrity","cyber securty","cybersecuirty","سائبر سیکیورٹی","سائبر سکیورٹی","security"],t:"Cybersecurity",noori:"Cybersecurity کمپیوٹرز، نیٹ ورکس، ڈیٹا اور لوگوں کو نقصان، چوری اور غلط استعمال سے بچانے کا علم اور عمل ہے — CIA (رازداری، درستگی، دستیابی) کی حفاظت۔",mano:"Cybersecurity کا مطلب ہے کمپیوٹر اور اپنی معلومات کو بُرے لوگوں سے محفوظ رکھنا، جیسے گھر کو تالا۔",harmi:"کمپیوٹر کو محفوظ رکھنا، جیسے دروازہ بند کرنا 🔒",ex:"مضبوط پاس ورڈ، MFA، اپ ڈیٹس، اور مشکوک لنک پر کلک نہ کرنا۔"}]},{id:"s2-identity",building:"cyber",order:2,icon:"🔑",tracks:["noori","mano"],skill:"passwords",skillName:"پاس ورڈ اور MFA",title:"Authentication، Authorization، پاس ورڈ اور MFA",en:"AuthN, AuthZ, Passwords & MFA",minutes:25,objective:"شناخت (AuthN) اور اجازت (AuthZ) کا فرق، passphrase کی مضبوطی، MFA اور password manager۔",lessons:[{t:"AuthN بمقابلہ AuthZ",h:"<p><b>Authentication</b>: آپ کون ہیں؟ (پاس ورڈ، فنگر پرنٹ)۔ <b>Authorization</b>: آپ کیا کر سکتے ہیں؟ (admin یا عام صارف)۔</p><p><b>MFA</b>: دو یا زیادہ ثبوت — جو جانتے ہیں (پاس ورڈ) + جو پاس ہے (فون/key) + جو آپ ہیں (فنگر پرنٹ)۔ OTP کبھی کسی کو نہ بتائیں۔</p>"},{t:"مضبوط passphrase",h:"<p>لمبائی سب سے اہم: <code>blue-cat-moon-42</code> چار بے ترتیب الفاظ۔ ہر اکاؤنٹ کا الگ پاس ورڈ — ایک لیک ہو تو باقی محفوظ (credential stuffing سے بچاؤ)۔ Password manager یاد رکھنے کا محفوظ طریقہ ہے۔</p>"}],mano:{lessons:[{t:"پاس ورڈ کا راز",h:"<p>لمبا پاس ورڈ = مضبوط 💪۔ کسی کو نہ بتاؤ، صرف ماما بابا کو۔ <b>MFA</b> ایک دوسرا تالا ہے۔</p>"}]},example:{t:"مثال",h:"<p><code>noori2017</code> → نام + سال = کمزور۔ <code>Tea-Kite-River-Orbit</code> → لمبا، بے ترتیب = مضبوط۔</p>"},activity:{type:"password",title:"Passphrase لیب (اصلی entropy حساب)",stages:[{name:"Beginner",task:"کم از کم 12 حروف کا پاس ورڈ بنائیں جس میں آپ کا نام نہ ہو۔",minLen:12,minBits:50},{name:"Intermediate",task:"4 الفاظ کا passphrase بنائیں (درمیان میں - لگا کر)، کم از کم 16 حروف۔",minLen:16,minWords:4,minBits:60},{name:"Advanced",task:"ایسا passphrase جس کی اندازاً طاقت 75 bits سے زیادہ ہو اور عام الفاظ (password, 123456, qwerty) نہ ہوں۔",minLen:18,minBits:75}]},activityMano:{type:"classify",title:"مضبوط یا کمزور؟",stages:[{name:"Beginner",buckets:["💪 مضبوط","😟 کمزور"],items:[["1234",1],["mano",1],["Sun-Kite-Tree-Blue",0],["password",1],["Red-Lion-Jumps-Far",0]]}]},quizMano:[{q:"اچھا پاس ورڈ کیسا ہوتا ہے؟",o:["لمبا اور مشکل","اپنا نام"],a:0,e:"لمبا پاس ورڈ مضبوط ہوتا ہے، اپنا نام آسانی سے اندازہ ہو جاتا ہے۔"},{q:"پاس ورڈ کس کو بتا سکتے ہیں؟",o:["صرف ماما بابا","سب دوستوں کو"],a:0,e:"پاس ورڈ راز ہے — صرف ماما بابا کو۔"},{q:"OTP کوڈ کوئی فون پر مانگے تو؟",o:["کبھی نہ بتاؤ، بڑوں کو بتاؤ","بتا دو"],a:0,e:"OTP کبھی کسی کو نہ بتائیں — بینک یا کمپنی کبھی نہیں مانگتی۔"}],quiz:[{q:"Authorization کیا طے کرتا ہے؟",o:["آپ کون ہیں","آپ کیا کر سکتے ہیں"],a:1,e:"AuthZ = اجازتیں۔"},{q:"ہر اکاؤنٹ کا الگ پاس ورڈ کیوں؟",o:["ایک لیک ہو تو باقی محفوظ","خوبصورتی"],a:0,e:"Credential stuffing سے بچاؤ۔"},{q:"کوئی فون پر OTP مانگے؟",o:["بتا دیں","کبھی نہ بتائیں"],a:1,e:"OTP صرف آپ کے لیے ہے۔"}],reflect:"آپ اپنا اگلا passphrase کیسے بنائیں گی؟ (اصلی پاس ورڈ یہاں نہ لکھیں!)",concepts:[{k:["password","pasword","passwrd","پاس ورڈ","passphrase"],t:"Passwords",noori:"مضبوط پاس ورڈ لمبا اور بے ترتیب ہوتا ہے (4 بے ترتیب الفاظ)، ہر اکاؤنٹ کے لیے الگ، اور password manager میں محفوظ۔",mano:"لمبا پاس ورڈ مضبوط ہوتا ہے، اسے کسی کو نہ بتاؤ۔",harmi:"پاس ورڈ ایک راز ہے، صرف ماما بابا جانتے ہیں 🤫"},{k:["mfa","2fa","two factor","multi factor","otp","ایم ایف اے"],t:"MFA",noori:"MFA میں پاس ورڈ کے ساتھ دوسرا ثبوت (فون ایپ، security key، فنگر پرنٹ) چاہیے۔ پاس ورڈ چوری ہونے پر بھی اکاؤنٹ بچتا ہے۔",mano:"MFA دروازے کا دوسرا تالا ہے۔"},{k:["authentication","authorization","authn","authz"],t:"AuthN vs AuthZ",noori:"Authentication شناخت ثابت کرتا ہے؛ Authorization طے کرتا ہے کہ کیا کرنے کی اجازت ہے۔"}]},{id:"s3-crypto",building:"cyber",order:3,icon:"🔐",tracks:["noori"],skill:"cryptography",skillName:"کرپٹوگرافی",title:"کرپٹوگرافی کی بنیاد",en:"Cryptography Fundamentals",minutes:30,objective:"encryption بمقابلہ hashing، symmetric/asymmetric keys، اور hash سے integrity جانچنا۔",lessons:[{t:"Encryption",h:"<p><b>Encryption</b> پیغام کو key سے ناقابل پڑھائی بناتا ہے؛ key سے واپس کھلتا ہے۔</p><ul><li><b>Symmetric</b> (AES): ایک ہی key سے بند/کھولنا — تیز۔</li><li><b>Asymmetric</b> (RSA/ECC): public key سے بند، private key سے کھولنا — HTTPS میں key کا تبادلہ۔</li></ul><p>Caesar cipher (حروف کو آگے کھسکانا) تاریخی کھیل ہے، آج محفوظ نہیں۔</p>"},{t:"Hashing",h:"<p><b>Hash</b> (SHA-256) کسی بھی ڈیٹا کا fingerprint ہے: ایک حرف بدلے تو پورا hash بدل جاتا ہے، اور اسے واپس اصل میں نہیں بدلا جا سکتا۔</p><p>استعمال: فائل کی integrity، ڈیجیٹل ثبوت (forensics)، اور پاس ورڈ محفوظ کرنا (salt + سست hash جیسے bcrypt/Argon2)۔</p>"}],example:{t:"مثال",h:'<p><code>SHA-256("abc")</code> = <code>ba7816bf…15ad</code>۔ <code>"abd"</code> کا hash بالکل مختلف۔</p>'},activity:{type:"crypto",title:"کرپٹو لیب (اصلی SHA-256)",stages:[{name:"Beginner",mode:"caesar",plain:"CYBER",shift:3,task:"CYBER کو shift 3 سے encrypt کریں۔"},{name:"Intermediate",mode:"caesar-decode",cipher:"KHOOR",task:"KHOOR کو decode کریں (shift 3)۔"},{name:"Advanced",mode:"hash",task:"دو فائلوں کے hash ملا کر بتائیں کون سی بدلی گئی۔",files:[["report_v1.txt","Total: 500"],["report_copy.txt","Total: 500"],["report_final.txt","Total: 900"]],changed:"report_final.txt"}]},quiz:[{q:"Hash کو واپس اصل میں بدلا جا سکتا ہے؟",o:["ہاں","نہیں (one-way)"],a:1,e:"Hash یک طرفہ ہے۔"},{q:"HTTPS key exchange میں کون سی قسم؟",o:["Asymmetric","صرف Caesar"],a:0,e:"Public/private key سے محفوظ تبادلہ۔"},{q:"پاس ورڈ ڈیٹا بیس میں کیسے رکھیں؟",o:["سادہ متن","salt + سست hash"],a:1,e:"bcrypt/Argon2 جیسے سست hash۔"}],reflect:"Encryption اور hashing میں فرق ایک مثال سے لکھیں۔",concepts:[{k:["encryption","encrypt","انکرپشن","cipher","aes","rsa"],t:"Encryption",noori:"Encryption ڈیٹا کو key سے ناقابل پڑھائی بناتی ہے۔ Symmetric (AES) ایک key، asymmetric (RSA/ECC) public/private key جوڑا۔",mano:"Encryption ایک خفیہ کوڈ ہے جسے صرف چابی والا پڑھ سکتا ہے۔"},{k:["hash","hashing","ہیش","sha256","sha-256","md5"],t:"Hashing",noori:"Hash ڈیٹا کا یک طرفہ fingerprint ہے؛ ایک حرف بدلے تو hash بدل جاتا ہے۔ Integrity اور پاس ورڈ (salt + bcrypt/Argon2) میں استعمال۔ MD5/SHA-1 اب کمزور مانے جاتے ہیں۔"}]},{id:"s4-web-owasp",building:"cyber",order:4,icon:"🕸️",tracks:["noori"],skill:"web-security",skillName:"ویب سیکیورٹی (OWASP)",title:"ویب ایپ سیکیورٹی اور OWASP Top 10",en:"Web App Security & OWASP Top 10",minutes:35,objective:"OWASP Top 10 کی اہم اقسام، SQL injection کیسے ہوتا ہے اور parameterized query کیسے روکتی ہے۔",lessons:[{t:"OWASP Top 10 (2021)",h:"<ol><li><b>Broken Access Control</b> — دوسرے کا ڈیٹا دیکھ لینا (IDOR)</li><li><b>Cryptographic Failures</b> — راز بغیر encryption</li><li><b>Injection</b> — SQL/command/XSS</li><li><b>Insecure Design</b></li><li><b>Security Misconfiguration</b></li><li><b>Vulnerable & Outdated Components</b></li><li><b>Identification & Authentication Failures</b></li><li><b>Software & Data Integrity Failures</b></li><li><b>Security Logging & Monitoring Failures</b></li><li><b>SSRF</b> — سرور سے اندرونی پتے منگوانا</li></ol>"},{t:"SQL Injection",h:"<p>کمزور کوڈ: <code>\"SELECT * FROM users WHERE name='\" + input + \"'\"</code>۔ اگر input = <code>' OR '1'='1</code> ہو تو شرط ہمیشہ سچ!</p><p>درست طریقہ: <b>parameterized query</b> — <code>WHERE name = ?</code> — ڈیٹا کبھی کوڈ نہیں بنتا۔ ساتھ میں input validation اور least-privilege DB اکاؤنٹ۔</p>"+i}],example:{t:"مثال: IDOR",h:"<p><code>/api/report?student=7</code> کو 8 کرنے سے کسی اور کی رپورٹ کھل گئی → سرور ہر درخواست پر ملکیت جانچے۔</p>"},activity:{type:"sqli",title:"SQL Injection لیب (بند ماحول)",stages:[{name:"Beginner",task:"کمزور لاگ ان میں دیکھیں کہ username کے خانے میں ' OR '1'='1 کیا کرتا ہے، پھر سمجھ کی تصدیق کریں۔",mode:"observe"},{name:"Intermediate",task:'"Safe mode" (parameterized) آن کر کے وہی input آزمائیں — لاگ ان ناکام ہونا چاہیے۔',mode:"defend"},{name:"Advanced",task:'input validation کا اصول لکھیں: username میں صرف حروف/نمبر/._- (3–20)۔ regex دیں جو حملہ روکے مگر "noori_9" قبول کرے۔',mode:"validate"}]},quiz:[{q:"SQL injection کا بہترین علاج؟",o:["Parameterized queries","صرف JavaScript سے روکنا"],a:0,e:"Client-side چیک بائی پاس ہو سکتا ہے؛ سرور پر parameterized۔"},{q:"IDOR کس زمرے میں؟",o:["Broken Access Control","Cryptographic Failures"],a:0,e:"ملکیت کی جانچ نہیں ہوئی۔"},{q:"SSRF کیا ہے؟",o:["سرور کو اندرونی پتے سے ڈیٹا منگوانے پر مجبور کرنا","پاس ورڈ لیک"],a:0,e:"Server-Side Request Forgery۔"}],reflect:"Broken access control سے بچنے کا ایک اصول لکھیں۔",concepts:[{k:["owasp","owasp top 10","top 10"],t:"OWASP Top 10",noori:"OWASP Top 10 ویب ایپس کے سب سے اہم خطرات کی فہرست ہے: Broken Access Control، Crypto Failures، Injection، Insecure Design، Misconfiguration، Outdated Components، Auth Failures، Integrity Failures، Logging Failures، SSRF۔"},{k:["sql injection","sqli","ایس کیو ایل انجیکشن","injection"],t:"SQL injection",noori:"جب user input سیدھا SQL میں جڑ جائے تو حملہ آور query بدل سکتا ہے۔ علاج: parameterized queries، input validation، least privilege، WAF ایک اضافی تہہ۔"},{k:["idor","access control","broken access"],t:"Broken access control",noori:"سرور کو ہر درخواست پر جانچنا چاہیے کہ یہ صارف اس چیز کا مالک/مجاز ہے یا نہیں۔"},{k:["ssrf"],t:"SSRF",noori:"SSRF میں حملہ آور سرور سے اندرونی/cloud metadata پتے منگواتا ہے۔ علاج: allowlist، اندرونی IPs بلاک، metadata v2۔"},{k:["csrf","xsrf"],t:"CSRF",noori:"CSRF میں دوسری سائٹ آپ کے لاگ ان براؤزر سے بغیر مرضی درخواست بھجواتی ہے۔ علاج: CSRF tokens، SameSite cookies۔"}]},{id:"s5-xss",building:"cyber",order:5,icon:"💉",tracks:["noori"],skill:"secure-coding",skillName:"محفوظ کوڈنگ",title:"XSS، output encoding اور محفوظ کوڈنگ",en:"XSS & Secure Coding",minutes:30,objective:"XSS کی اقسام، output encoding سے روک تھام، اور escape فنکشن لکھنا جسے اصل ٹیسٹ جانچیں۔",lessons:[{t:"XSS",h:'<p><b>Cross-Site Scripting</b>: صارف کا متن HTML بن کر چل جائے۔ مثلاً تبصرہ <code>&lt;img src=x onerror=alert(1)&gt;</code>۔</p><ul><li><b>Stored</b> — ڈیٹا بیس میں محفوظ ہو کر سب کو لگے</li><li><b>Reflected</b> — URL سے فوراً واپس</li><li><b>DOM</b> — JavaScript خود غیر محفوظ طریقے سے لکھے</li></ul><p>علاج: <b>output encoding</b> (<code>&lt;</code> → <code>&amp;lt;</code>)، <code>textContent</code> استعمال کریں، Content-Security-Policy۔</p><p class="ac-note">اسی اکیڈمی میں بھی Byte اور Master Classroom میں یہ خامی تھی جو اب ٹھیک کی گئی ہے — حقیقی مثال!</p>'}],example:{t:"مثال",h:"<pre>el.innerHTML = comment;   // ❌\nel.textContent = comment; // ✅</pre>"},activity:{type:"js",title:"escapeHtml لکھیں (اصلی ٹیسٹ)",stages:[{name:"Beginner",starter:"function escapeLt(s) {\n  // < کو &lt; سے بدلیں\n}",fn:"escapeLt",tests:[[["<b>"],"&lt;b>"],[["a<b<c"],"a&lt;b&lt;c"]]},{name:"Intermediate",starter:"function escapeHtml(s) {\n  // & < > \" ' سب escape کریں\n}",fn:"escapeHtml",tests:[[["<script>"],"&lt;script&gt;"],[["\"x\" & 'y'"],"&quot;x&quot; &amp; &#39;y&#39;"],[["safe"],"safe"]]},{name:"Advanced",starter:"function isSafeUrl(u) {\n  // صرف http: یا https: والے لنک true؛ javascript: وغیرہ false\n}",fn:"isSafeUrl",tests:[[["https://example.com"],!0],[["javascript:alert(1)"],!1],[["  JavaScript:alert(1)"],!1],[["http://a.b"],!0],[["data:text/html,x"],!1]]}]},quiz:[{q:"XSS سے بچاؤ کا اہم طریقہ؟",o:["Output encoding / textContent","پاس ورڈ لمبا کرنا"],a:0,e:"متن کو HTML نہ بننے دیں۔"},{q:"Stored XSS کیوں خطرناک؟",o:["ہر دیکھنے والے کو لگتا ہے","صرف ایک بار چلتا ہے"],a:0,e:"ڈیٹا بیس میں محفوظ رہ کر بار بار چلتا ہے۔"}],reflect:"innerHTML کب خطرناک ہے؟",concepts:[{k:["xss","cross site scripting","cross-site scripting","ایکس ایس ایس"],t:"XSS",noori:"XSS میں حملہ آور کا متن صفحے پر script بن کر چلتا ہے۔ علاج: output encoding، textContent، CSP، اور input validation۔"},{k:["secure coding","محفوظ کوڈنگ","input validation","output encoding"],t:"Secure coding",noori:"Input کی allowlist جانچ، output encoding، parameterized queries، secrets کوڈ سے باہر، کم اجازت، اور errors میں حساس معلومات نہ دکھانا۔"}]},{id:"s6-api-security",building:"cyber",order:6,icon:"🧷",tracks:["noori"],skill:"api-security",skillName:"API سیکیورٹی",title:"API سیکیورٹی",en:"API Security",minutes:25,objective:"API کی عام کمزوریاں (BOLA، ضرورت سے زیادہ ڈیٹا، rate limit نہ ہونا) پہچاننا اور کنٹرول تجویز کرنا۔",lessons:[{t:"OWASP API Top خطرات",h:"<ul><li><b>BOLA</b> (Broken Object Level Authorization): <code>/api/orders/1001</code> کو 1002 کرنے سے کسی اور کا آرڈر۔</li><li><b>Excessive data exposure</b>: API پورا user object (پاس ورڈ hash، فون) بھیج دے۔</li><li><b>Missing rate limiting</b>: ہزاروں درخواستیں — brute force یا scraping۔</li><li><b>Broken authentication</b>: کمزور tokens، کبھی ختم نہ ہونے والے sessions۔</li></ul><p>کنٹرولز: ہر object پر ملکیت کی جانچ، صرف ضروری fields، rate limits، مختصر مدت کے tokens، لاگنگ۔</p>"}],example:{t:"مثال",h:"<p>ایک حقیقی کیس (Optus 2022 — کیس لائبریری دیکھیں) میں رپورٹس کے مطابق ایک API بغیر authentication کے صارفین کا ڈیٹا دے رہی تھی۔</p>"},activity:{type:"classify",title:"خطرہ پہچانیں",stages:[{name:"Beginner",buckets:["BOLA","زیادہ ڈیٹا","Rate limit نہیں"],items:[["id بدل کر دوسرے کی پروفائل",0],["جواب میں password_hash بھی",1],["ایک منٹ میں 10,000 لاگ ان کوششیں قبول",2],["order_id بدل کر دوسرے کا بل",0],["جواب میں سب کے فون نمبر",1]]},{name:"Intermediate",buckets:["اچھا کنٹرول","کمزور"],items:[["ہر درخواست پر owner_id == user_id جانچ",0],["API key فرنٹ اینڈ JavaScript میں",1],["15 منٹ کے access tokens",0],["صرف client پر چھپانا",1],["429 Too Many Requests",0]]}]},quiz:[{q:"BOLA سے بچاؤ؟",o:["ہر object پر سرور ملکیت جانچے","id کو مشکل بنا دیں بس"],a:0,e:"مشکل id بھی اندازہ ہو سکتی ہے؛ authorization ضروری۔"},{q:"429 کا مطلب؟",o:["Too Many Requests","OK"],a:0,e:"Rate limiting کا جواب۔"}],reflect:"اگر آپ اسکول کی API بنائیں تو کون سے 3 کنٹرول لگائیں گی؟",concepts:[{k:["api security","bola","rate limit","rate limiting"],t:"API security",noori:"API سیکیورٹی: ہر object پر authorization (BOLA سے بچاؤ)، صرف ضروری ڈیٹا، rate limiting، مضبوط اور مختصر مدت کے tokens، input validation، لاگنگ۔"}]},{id:"s7-headers",building:"cyber",order:7,icon:"📨",tracks:["noori"],skill:"security-headers",skillName:"سیکیورٹی ہیڈرز اور کوکیز",title:"سیکیورٹی ہیڈرز اور محفوظ کوکیز",en:"Security Headers & Secure Cookies",minutes:25,objective:"HSTS، CSP، X-Content-Type-Options، frame-ancestors اور cookie flags (Secure, HttpOnly, SameSite) کا مقصد۔",lessons:[{t:"اہم ہیڈرز",h:"<ul><li><code>Strict-Transport-Security</code> — ہمیشہ HTTPS</li><li><code>Content-Security-Policy</code> — کہاں سے script چل سکتا ہے (XSS کی دوسری تہہ)</li><li><code>X-Content-Type-Options: nosniff</code></li><li><code>Content-Security-Policy: frame-ancestors 'none'</code> یا <code>X-Frame-Options: DENY</code> — clickjacking سے بچاؤ</li><li><code>Referrer-Policy</code></li></ul><p>Cookie: <code>Set-Cookie: session=…; Secure; HttpOnly; SameSite=Lax</code> — HTTPS پر ہی جائے، JS نہ پڑھ سکے، دوسری سائٹ سے کم بھیجی جائے۔</p>"}],example:{t:"مثال",h:"<pre>Set-Cookie: sid=abc   ❌\nSet-Cookie: sid=abc; Secure; HttpOnly; SameSite=Strict ✅</pre>"},activity:{type:"headers",title:"ہیڈر آڈٹ",stages:[{name:"Beginner",response:"HTTP/1.1 200 OK\nContent-Type: text/html\nSet-Cookie: sid=91af; Path=/",missing:["strict-transport-security","content-security-policy","x-content-type-options"],cookieFlags:["secure","httponly","samesite"]},{name:"Intermediate",response:"HTTP/1.1 200 OK\nStrict-Transport-Security: max-age=31536000\nX-Content-Type-Options: nosniff\nSet-Cookie: sid=91af; Secure; Path=/",missing:["content-security-policy"],cookieFlags:["httponly","samesite"]},{name:"Advanced",write:!0,task:"ایسا Set-Cookie ہیڈر لکھیں جو Secure، HttpOnly اور SameSite (Lax یا Strict) ہو، اور ایک CSP جو default-src 'self' رکھے۔"}]},quiz:[{q:"HttpOnly کیا روکتا ہے؟",o:["JavaScript سے cookie پڑھنا","HTTPS"],a:0,e:"XSS کے دوران cookie چوری مشکل۔"},{q:"HSTS کا کام؟",o:["براؤزر کو ہمیشہ HTTPS استعمال کروانا","تصاویر چھوٹی کرنا"],a:0,e:"Downgrade حملوں سے بچاؤ۔"}],reflect:'CSP کو XSS کی "دوسری تہہ" کیوں کہتے ہیں؟',concepts:[{k:["security headers","csp","hsts","headers","ہیڈرز","x-frame-options"],t:"Security headers",noori:"HSTS (ہمیشہ HTTPS)، CSP (script کے ذرائع محدود)، nosniff، frame-ancestors/X-Frame-Options (clickjacking)، Referrer-Policy۔"},{k:["cookie","cookies","httponly","samesite","secure cookie","کوکی"],t:"Secure cookies",noori:"Session cookie پر Secure، HttpOnly اور SameSite لگائیں۔"}]},{id:"s8-waf",building:"cyber",order:8,icon:"🧱",tracks:["noori"],skill:"waf",skillName:"WAF",title:"WAF عملی تربیت",en:"Web Application Firewall — Practical",minutes:45,objective:"WAF درخواست کیسے جانچتا ہے، managed بمقابلہ custom rules، false positives، normalization، bypass کے تصورات، origin protection اور retesting — سب ایک بند لیب میں۔",lessons:[{t:"WAF کیا کرتا ہے؟",h:'<p>WAF ویب ایپ کے سامنے کھڑا گارڈ ہے جو ہر HTTP درخواست (URL، query، headers، body) کو قواعد سے جانچتا ہے اور <b>allow / block / log</b> کرتا ہے۔</p><ul><li><b>Managed rules</b>: فراہم کنندہ کے تیار شدہ signatures (مثلاً OWASP Core Rule Set)۔</li><li><b>Custom rules</b>: آپ کی ایپ کے لیے خاص قواعد (مثلاً /admin صرف دفتر کے IP سے)۔</li><li><b>Rate rules</b>: ایک IP سے بہت زیادہ درخواستیں۔</li></ul><p class="ac-warn">WAF ایک اضافی تہہ ہے، کمزور کوڈ کا علاج نہیں۔ اصل حل secure coding ہے۔</p>'},{t:"Normalization اور bypass کے تصورات",h:"<p>حملہ آور ایک ہی چیز کو مختلف شکل میں لکھتے ہیں: <code>%27</code> (URL encoding)، <code>%2527</code> (دوہری encoding)، <code>UnIoN</code> (حروف کی شکل)، <code>/**/</code> (تبصرے)۔ اگر WAF پہلے <b>normalize</b> (decode، lowercase، فالتو space/تبصرے ہٹانا) نہ کرے تو signature چوک جاتا ہے۔</p><p><b>Origin bypass</b>: اگر سرور کا اصل IP براہِ راست کھلا ہو تو حملہ آور WAF کے گرد گھوم کر سیدھا جا سکتا ہے → origin کو صرف WAF کے IPs سے ٹریفک قبول کرنی چاہیے۔</p>"},{t:"False positives، tuning اور retesting",h:"<p><b>False positive</b>: جائز صارف بلاک (مثلاً نام <code>O'Brien</code> میں ' کی وجہ سے)۔ <b>False negative</b>: حملہ گزر گیا۔</p><p>عمل: پہلے <b>log/count mode</b> میں چلائیں → لاگز پڑھیں → قاعدہ تنگ کریں (صرف متعلقہ فیلڈ/راستہ) → block mode → <b>retest</b> (حملے بھی، جائز ٹریفک بھی) → نگرانی جاری۔</p>"+i}],example:{t:"مثال: لاگ لائن",h:"<pre>2026-10-31T10:02Z BLOCK rule=SQLI-942100 ip=203.0.113.9 uri=/search?q=1%27%20OR%201=1--</pre><p>قاعدہ 942100 نے normalize کے بعد <code>' OR 1=1--</code> پکڑا۔</p>"},activity:{type:"waf",title:"WAF لیب — اپنی ایپ کی حفاظت کریں (مکمل طور پر فرضی ٹریفک)",stages:[{name:"Beginner",task:"Managed SQLi اور XSS قواعد آن کریں۔ کم از کم 4 میں سے 4 بنیادی حملے بلاک اور کوئی جائز درخواست بلاک نہ ہو۔",suite:"basic"},{name:"Intermediate",task:'"O\'Brien" جیسے جائز ناموں پر false positive آ رہا ہے۔ قاعدے کو صرف حملے والے pattern تک تنگ کریں یا name فیلڈ کے لیے exclusion بنائیں — سب حملے بلاک، 0 false positives۔',suite:"tuning"},{name:"Advanced",task:"Encoded اور mixed-case bypass کوششیں گزر رہی ہیں، اور origin سیدھا کھلا ہے۔ normalization آن کریں، origin کو صرف WAF سے ٹریفک تک محدود کریں، اور retest پاس کریں۔",suite:"advanced"}]},quiz:[{q:"نیا WAF قاعدہ پہلے کس mode میں؟",o:["Log/count mode","فوراً block"],a:0,e:"پہلے دیکھیں جائز ٹریفک تو نہیں رک رہی۔"},{q:"%2527 کیا ہے؟",o:["دوہری URL encoding شدہ '","عام نمبر"],a:0,e:"%25 = %، پھر %27 = '۔"},{q:"Origin bypass کا علاج؟",o:["Origin صرف WAF IPs سے ٹریفک قبول کرے","WAF بند کریں"],a:0,e:"سیدھا راستہ بند کریں۔"},{q:"WAF کے ہوتے ہوئے بھی SQLi کا اصل علاج؟",o:["Parameterized queries","مزید WAF قواعد ہی کافی"],a:0,e:"WAF اضافی تہہ ہے۔"}],reflect:"False positive اور false negative میں سے آپ کی ایپ کے لیے کون سا زیادہ نقصان دہ ہے، اور کیوں؟",concepts:[{k:["waf","web application firewall","ڈبلیو اے ایف","firewall web"],t:"WAF",noori:"WAF ویب درخواستوں کو قواعد سے جانچتا ہے (managed + custom + rate rules)۔ اچھا WAF پہلے normalize کرتا ہے، log mode میں ٹیون ہوتا ہے، origin کو صرف WAF سے ٹریفک ملتی ہے، اور ہر تبدیلی کے بعد retest ہوتا ہے۔ یہ secure coding کا متبادل نہیں۔",steps:["Managed rules log mode میں","لاگز سے false positives دیکھیں","قواعد تنگ کریں/exclusions","Normalization آن","Origin lock","Block mode + retest"]},{k:["false positive","false negative","فالس پازیٹو"],t:"False positives",noori:"False positive: جائز چیز کو حملہ سمجھنا۔ False negative: حملہ چھوٹ جانا۔ Tuning دونوں کو کم کرتی ہے۔"},{k:["bypass","waf bypass","normalization","encoding","بائی پاس"],t:"Bypass & normalization",noori:"Bypass کی کوششیں encoding، حروف کی شکل یا تبصروں سے signature سے بچتی ہیں۔ دفاع: decode/normalize پھر جانچ، allowlists، اور origin lock۔ یہ صرف اجازت والی لیب میں آزمائیں۔"}]},{id:"s9-vuln-pentest",building:"cyber",order:9,icon:"🔎",tracks:["noori"],skill:"vulnerabilities",skillName:"کمزوریاں اور جانچ کا طریقہ",title:"Vulnerability Assessment اور Pentest طریقہ کار",en:"Vulnerability Assessment & Pentest Methodology",minutes:35,objective:"اجازت سے رپورٹ تک کا پورا عمل: scope، asset list، attack surface، کمزوری، رسک، ثبوت، remediation، retest، رپورٹ۔",lessons:[{t:"مرحلے",h:"<ol><li><b>اجازت اور scope</b> (تحریری) — کیا جانچنا ہے، کیا نہیں، کب۔</li><li><b>Asset identification</b> — سرورز، ڈومینز، ایپس۔</li><li><b>Attack surface</b> — کھلے پورٹس، لاگ ان صفحات، APIs۔</li><li><b>Vulnerability identification</b> — پرانا سافٹ ویئر، misconfiguration، کمزور auth۔</li><li><b>Risk</b> — اثر × امکان۔</li><li><b>Evidence</b> — screenshots، requests، وقت، hash۔</li><li><b>Remediation</b> — patch، config، کوڈ fix۔</li><li><b>Retest</b> — تصدیق کہ ٹھیک ہوا۔</li><li><b>Report</b> — خلاصہ، تفصیل، ترجیح، اقدامات۔</li></ol>"+i}],example:{t:"مثال: ایک finding",h:"<p><b>عنوان:</b> Admin پینل پر MFA نہیں۔ <b>رسک:</b> High۔ <b>ثبوت:</b> 10:02 پر صرف پاس ورڈ سے لاگ ان۔ <b>حل:</b> MFA لازمی۔ <b>Retest:</b> 2 نومبر — پاس۔</p>"},activity:{type:"order",title:"جانچ کا درست عمل",stages:[{name:"Beginner",items:["تحریری اجازت اور scope","Assets کی فہرست","کمزوریاں ڈھونڈیں","رپورٹ لکھیں"]},{name:"Intermediate",items:["تحریری اجازت اور scope","Assets اور attack surface","کمزوری کی شناخت","رسک کا اندازہ","ثبوت جمع کریں","Remediation تجویز","Retest","حتمی رپورٹ"]}]},quiz:[{q:"جانچ سے پہلے لازمی؟",o:["تحریری اجازت اور scope","تیز انٹرنیٹ"],a:0,e:"اجازت کے بغیر جانچ غیر قانونی ہے۔"},{q:"Retest کیوں؟",o:["تصدیق کہ fix کام کر گیا","وقت گزارنے کے لیے"],a:0,e:"Fix کی تصدیق۔"}],reflect:"ایک اچھی رپورٹ میں کیا لازمی ہونا چاہیے؟",concepts:[{k:["vulnerability","vulnerabilities","کمزوری","vuln","vulnerability assessment"],t:"Vulnerability assessment",noori:"کمزوریوں کی منظم تلاش: اجازت/scope → assets → attack surface → شناخت → رسک → ثبوت → remediation → retest → رپورٹ۔"},{k:["pentest","penetration testing","pen test","ethical hacking","ہیکنگ","hacking","hacker","ہیکر"],t:"Penetration testing",noori:"Penetration testing اجازت کے ساتھ حملہ آور کی طرح سوچ کر کمزوریاں ثابت کرنا اور رپورٹ کرنا ہے۔ بغیر تحریری اجازت کسی کا سسٹم جانچنا جرم ہے۔ مشق صرف اپنی لیب میں۔",mano:"اچھے ہیکر اجازت لے کر کمزوری ڈھونڈتے اور ٹھیک کرواتے ہیں۔"},{k:["ethics","legal","permission","اجازت","قانون","peca"],t:"Ethics & permission",noori:"سیکیورٹی کام ہمیشہ اجازت سے: اپنی چیزیں، تحریری اجازت والا scope، یا بند لیب۔ پاکستان میں PECA 2016 غیر مجاز رسائی کو جرم قرار دیتا ہے۔"}]},{id:"s10-malware",building:"cyber",order:10,icon:"🦠",tracks:["noori","mano"],skill:"malware",skillName:"مالویئر کی بنیاد",title:"مالویئر کی بنیاد اور محفوظ تجزیہ",en:"Malware Fundamentals & Safe Analysis",minutes:25,objective:"مالویئر کی اقسام، پھیلنے کے راستے، نشانیاں، اور محفوظ تجزیے کے اصول (کبھی اپنے کمپیوٹر پر نہ چلائیں)۔",lessons:[{t:"اقسام",h:"<ul><li><b>Virus/Worm</b> — پھیلنے والا کوڈ</li><li><b>Trojan</b> — اچھا بن کر آنے والا</li><li><b>Ransomware</b> — فائلیں encrypt کر کے تاوان</li><li><b>Spyware/Keylogger</b> — جاسوسی</li><li><b>Infostealer</b> — براؤزر کے پاس ورڈ/cookies چوری</li></ul><p>راستے: ای میل attachments، جعلی ڈاؤن لوڈ، pirated سافٹ ویئر، USB۔</p>"},{t:"محفوظ تجزیہ",h:'<p>ماہرین مالویئر کو <b>isolated VM/sandbox</b> میں، انٹرنیٹ سے کٹے ماحول میں جانچتے ہیں۔ پہلے <b>static</b> (hash، strings، metadata)، پھر <b>dynamic</b> (کنٹرولڈ ماحول میں رویہ)۔ IOC (hash، domain، IP) شیئر کیے جاتے ہیں۔</p><p class="ac-warn">بچوں کے لیے اصول: مشکوک فائل ہو تو کچھ نہ کھولیں، فوراً بڑوں کو بتائیں۔</p>'}],mano:{lessons:[{t:"کمپیوٹر کا بخار",h:"<p>وائرس کمپیوٹر کو بیمار کرتا ہے 🤒۔ انجان فائل نہ کھولو، صرف اسکول/ماما بابا کی اجازت والی ایپس ڈاؤن لوڈ کرو، اور کچھ عجیب ہو تو فوراً بتاؤ۔</p>"}]},example:{t:"مثال",h:"<p><code>free_game_crack.exe</code> ڈاؤن لوڈ → infostealer → براؤزر کے محفوظ پاس ورڈ چوری۔ حل: صرف آفیشل اسٹور، MFA، Defender۔</p>"},activity:{type:"classify",title:"محفوظ یا خطرناک عمل؟",stages:[{name:"Beginner",buckets:["✅ محفوظ","⚠️ خطرناک"],items:[["آفیشل اسٹور سے ایپ",0],["crack والا گیم",1],["انجان USB لگانا",1],["Windows اپ ڈیٹ",0],["ای میل کی .exe فائل کھولنا",1]]},{name:"Advanced",buckets:["Static تجزیہ","Dynamic تجزیہ","کبھی نہیں"],items:[["فائل کا SHA-256 نکالنا",0],["strings دیکھنا",0],["بند VM میں چلا کر رویہ دیکھنا",1],["اپنے گھریلو لیپ ٹاپ پر چلا کر دیکھنا",2],["نیٹ ورک سے کٹے sandbox میں رویہ ریکارڈ",1]]}]},quiz:[{q:"Ransomware کیا کرتا ہے؟",o:["فائلیں encrypt کر کے پیسے مانگتا ہے","کمپیوٹر تیز کرتا ہے"],a:0,e:"بیک اپ اور اپ ڈیٹس بہترین دفاع ہیں۔"},{q:"مشکوک فائل کا تجزیہ کہاں؟",o:["بند sandbox/VM","اپنے روزمرہ کمپیوٹر پر"],a:0,e:"Isolation ضروری ہے۔"}],quizMano:[{q:"انجان فائل آئی تو؟",o:["کھول لو","بڑوں کو بتاؤ"],a:1,e:"بڑوں کو بتانا سب سے محفوظ ہے۔"}],reflect:"Ransomware سے بچنے کے لیے گھر میں کون سی عادت اپنائیں؟",concepts:[{k:["malware","virus","وائرس","مالویئر","trojan","worm","ransomware","رینسم ویئر"],t:"Malware",noori:"Malware نقصان دہ سافٹ ویئر ہے: virus، worm، trojan، ransomware، spyware، infostealer۔ بچاؤ: اپ ڈیٹس، آفیشل ذرائع، MFA، بیک اپ، antivirus۔ تجزیہ صرف isolated sandbox میں۔",mano:"وائرس کمپیوٹر کو بیمار کرنے والا پروگرام ہے۔ انجان فائل نہ کھولو اور بڑوں کو بتاؤ۔",harmi:"عجیب چیز آئے تو ماما بابا کو بتاؤ 🙋"}]},{id:"s11-firewall-endpoint",building:"cyber",order:11,icon:"🚧",tracks:["noori"],skill:"firewall-endpoint",skillName:"فائر وال اور اینڈ پوائنٹ",title:"فائر وال اور اینڈ پوائنٹ سیکیورٹی",en:"Firewalls & Endpoint Security",minutes:30,objective:"فائر وال قواعد (first match، default deny) لکھنا جنہیں اصل rule engine جانچے؛ EDR/antivirus/patching کا کردار۔",lessons:[{t:"فائر وال",h:"<p>فائر وال ٹریفک کو source، destination، port اور protocol سے <b>allow/deny</b> کرتا ہے۔ قواعد اوپر سے نیچے پڑھے جاتے ہیں؛ پہلا match فیصلہ کرتا ہے۔ آخر میں <b>default deny</b>۔</p><pre>1 allow tcp any -> web 443\n2 allow tcp office -> web 22\n3 deny  any any -> any any</pre>"},{t:"Endpoint",h:"<p>Endpoint = لیپ ٹاپ/فون/سرور۔ حفاظت: OS اور ایپ updates، antivirus/<b>EDR</b> (رویے کی نگرانی)، disk encryption (BitLocker)، standard user اکاؤنٹ، screen lock، اور ایپس کی allowlist۔</p>"}],example:{t:"مثال",h:"<p>ویب سرور کو صرف 443 دنیا کے لیے، SSH (22) صرف دفتر کے IP سے، باقی سب بند۔</p>"},activity:{type:"firewall",title:"فائر وال رول لیب (اصلی rule engine)",stages:[{name:"Beginner",task:"ویب سرور کو انٹرنیٹ سے صرف HTTPS (443) ملے، باقی سب بند۔",tests:"fw1"},{name:"Intermediate",task:"SSH (22) صرف office (10.0.5.0/24) سے؛ HTTPS سب سے؛ باقی بند۔",tests:"fw2"},{name:"Advanced",task:"Database (3306) صرف web سرور (10.0.1.10) سے؛ انٹرنیٹ سے DB بالکل نہیں؛ default deny۔",tests:"fw3"}]},quiz:[{q:"Default deny کا مطلب؟",o:["جو اجازت نہیں وہ بند","سب کھلا"],a:0,e:"محفوظ ڈیفالٹ۔"},{q:"EDR کیا کرتا ہے؟",o:["Endpoint پر مشکوک رویے کی نگرانی اور ردعمل","ویب صفحے بنانا"],a:0,e:"Endpoint Detection & Response۔"}],reflect:"آپ کے لیپ ٹاپ پر کون سی 3 endpoint حفاظتیں ہونی چاہییں؟",concepts:[{k:["firewall","فائر وال","فایروال","fire wall"],t:"Firewall",noori:"فائر وال قواعد سے ٹریفک allow/deny کرتا ہے؛ اوپر سے نیچے پہلا match؛ آخر میں default deny۔ صرف ضروری پورٹس کھولیں۔",mano:"فائر وال ایک چوکیدار ہے جو صرف اجازت والے مہمان اندر آنے دیتا ہے۔"},{k:["endpoint","edr","antivirus","اینٹی وائرس"],t:"Endpoint security",noori:"Updates، antivirus/EDR، disk encryption، standard user، screen lock اور app allowlisting۔"}]},{id:"s12-soc-siem",building:"cyber",order:12,icon:"📡",tracks:["noori"],skill:"log-analysis",skillName:"لاگ تجزیہ",title:"لاگنگ، SIEM اور SOC آپریشنز",en:"Logging, SIEM & SOC Operations",minutes:35,objective:"لاگز سے سوالات کرنا، alert triage (true/false positive)، اور escalation؛ ایک اصلی query انجن پر مشق۔",lessons:[{t:"SOC اور SIEM",h:"<p><b>SOC</b> وہ ٹیم ہے جو 24/7 نگرانی کرتی ہے۔ <b>SIEM</b> سب لاگز (لاگ ان، فائر وال، ویب، endpoint) جمع کر کے تلاش اور alerts بناتا ہے۔</p><p>Triage: (1) alert پڑھیں (2) سیاق: کون، کہاں، کب (3) دوسرے لاگز سے تصدیق (4) فیصلہ: true positive / false positive / مزید جانچ (5) escalation اور دستاویز۔</p>"},{t:"Query",h:"<p>اس لیب کی query زبان: <code>result=FAILED</code>، <code>ip=45.13.0.9 user=admin</code>، <code>count by ip where result=FAILED</code>۔</p>"}],example:{t:"مثال",h:'<p>Alert: "admin کے 20 ناکام لاگ ان پھر 1 کامیاب"۔ اسی IP سے 2 منٹ بعد /export → ممکنہ اکاؤنٹ قبضہ → escalate۔</p>'},activity:{type:"logs",title:"SOC تجزیہ لیب (فرضی لاگز، اصلی query انجن)",dataset:"soc1",stages:[{name:"Beginner",task:"کتنی لاگ ان کوششیں FAILED ہیں؟",answer:"count_failed"},{name:"Intermediate",task:"سب سے زیادہ FAILED والا IP کون سا ہے؟",answer:"top_failed_ip"},{name:"Advanced",task:"اسی IP سے کس user میں کامیاب لاگ ان ہوا؟ (brute force کامیاب)",answer:"compromised_user"}]},quiz:[{q:"False positive alert کیا ہے؟",o:["Alert آیا مگر حملہ نہیں تھا","حملہ ہوا مگر alert نہیں"],a:0,e:"Triage سے فرق کرتے ہیں۔"},{q:"SIEM کا کام؟",o:["لاگز جمع، تلاش اور alerts","گیم بنانا"],a:0,e:"Security Information and Event Management۔"}],reflect:"ایک اچھا SOC تجزیہ کار alert پر جلدی فیصلہ کیوں نہیں کرتا؟",concepts:[{k:["soc","siem","log","logs","لاگ","لاگز","alert","triage","log analysis"],t:"SOC & SIEM",noori:"SIEM لاگز جمع کر کے تلاش اور alerts بناتا ہے؛ SOC ٹیم triage کرتی ہے: سیاق، دوسرے ذرائع سے تصدیق، true/false positive، escalation، دستاویز۔",mano:"لاگز کمپیوٹر کی ڈائری ہیں جن سے پتا چلتا ہے کیا ہوا۔",steps:["Alert پڑھیں","کون/کہاں/کب","دوسرے لاگز سے تصدیق","فیصلہ","Escalate اور لکھیں"]}]},{id:"s13-incident-forensics",building:"cyber",order:13,icon:"🚨",tracks:["noori","mano"],skill:"incident-response",skillName:"انسیڈنٹ رسپانس",title:"انسیڈنٹ رسپانس، فارنزکس اور ثبوت",en:"Incident Response, Forensics & Evidence",minutes:30,objective:"NIST lifecycle، chain of custody، hash سے ثبوت کی integrity، اور timeline بنانا۔",lessons:[{t:"Lifecycle",h:"<ol><li><b>Preparation</b> — منصوبہ، رابطے، بیک اپ</li><li><b>Detection & Analysis</b> — کیا ہوا، کتنا</li><li><b>Containment</b> — پھیلاؤ روکیں (اکاؤنٹ لاک، مشین الگ)</li><li><b>Eradication</b> — وجہ ختم</li><li><b>Recovery</b> — محفوظ واپسی، نگرانی</li><li><b>Lessons learned</b> — بہتری</li></ol>"},{t:"ثبوت",h:"<p><b>Chain of custody</b>: ہر ثبوت کس کے پاس، کب، کیوں — لکھا جائے۔ ثبوت کا <b>SHA-256</b> لیں تاکہ ثابت ہو بدلا نہیں۔ اصل پر کام نہ کریں، کاپی پر کریں۔ وقت ہمیشہ ایک time zone (UTC) میں۔</p>"}],mano:{lessons:[{t:"سراغ رساں",h:"<p>کچھ غلط ہو تو 🛑 رکو، 📸 ثبوت سنبھالو، 🙋 بڑوں کو بتاؤ، 🔧 مل کر ٹھیک کرو۔</p>"}]},example:{t:"مثال",h:"<p>10:01 brute force → 10:02 admin لاگ ان → 10:03 /export → 10:05 SOC alert → 10:07 IP block اور پاس ورڈ ری سیٹ (containment)۔</p>"},activity:{type:"order",title:"Incident timeline اور lifecycle",stages:[{name:"Beginner",items:["Preparation","Detection & Analysis","Containment","Eradication","Recovery","Lessons learned"]},{name:"Intermediate",items:["10:01 بار بار ناکام لاگ ان","10:02 admin کامیاب لاگ ان","10:03 ڈیٹا export","10:05 SOC alert","10:07 IP block اور پاس ورڈ ری سیٹ"]},{name:"Advanced",items:["ثبوت کی جگہ اور وقت نوٹ کریں","اصل کی forensic کاپی بنائیں","دونوں کا SHA-256 ملائیں","Chain of custody فارم بھریں","صرف کاپی پر تجزیہ"]}]},quiz:[{q:"Containment کا مقصد؟",o:["نقصان کا پھیلاؤ روکنا","رپورٹ لکھنا"],a:0,e:"پہلے آگ پھیلنے سے روکیں۔"},{q:"ثبوت کا hash کیوں؟",o:["ثابت کرنے کے لیے کہ بدلا نہیں","فائل چھوٹی کرنے کے لیے"],a:0,e:"Integrity کا ثبوت۔"}],quizMano:[{q:"کمپیوٹر پر کچھ عجیب ہو تو پہلے؟",o:["چھپا دو","رکو اور بڑوں کو بتاؤ"],a:1,e:"بتانا بہادری ہے۔"}],reflect:"Lessons learned میٹنگ کیوں ضروری ہے؟",concepts:[{k:["incident response","incident","انسیڈنٹ","ir","breach","hack ho gaya","hack hogaya"],t:"Incident response",noori:"NIST lifecycle: Preparation → Detection & Analysis → Containment → Eradication → Recovery → Lessons learned۔",mano:"کچھ غلط ہو تو رکو، ثبوت سنبھالو، بڑوں کو بتاؤ۔",harmi:"کچھ عجیب ہو تو ماما بابا کو بتاؤ 🙋"},{k:["forensics","forensic","فارنزکس","evidence","ثبوت","chain of custody"],t:"Digital forensics",noori:"ثبوت محفوظ کریں، forensic کاپی پر کام کریں، SHA-256 سے integrity، chain of custody، اور UTC timeline۔"}]},{id:"s14-cloud",building:"cyber",order:14,icon:"☁️",tracks:["noori"],skill:"cloud-security",skillName:"کلاؤڈ سیکیورٹی",title:"کلاؤڈ سیکیورٹی",en:"Cloud Security",minutes:25,objective:"shared responsibility، IAM least privilege، public storage، MFA اور cloud logging کی اہمیت۔",lessons:[{t:"Shared responsibility",h:"<p>کلاؤڈ فراہم کنندہ (AWS/Azure/GCP) ڈیٹا سینٹر اور ہارڈویئر محفوظ کرتا ہے؛ <b>آپ</b> اپنی سیٹنگز، ڈیٹا، شناخت اور رسائی کے ذمہ دار ہیں۔</p><ul><li>Storage bucket عوامی نہ ہو (جب تک واقعی ضرورت نہ ہو)۔</li><li>IAM: ہر سروس کو کم سے کم اجازت۔</li><li>ہر اکاؤنٹ پر MFA، خاص طور پر admin۔</li><li>Access keys کو گھمائیں، کوڈ میں نہ رکھیں۔</li><li>Logging (مثلاً CloudTrail) آن رکھیں۔</li></ul>"}],example:{t:"مثال",h:"<p>کیس لائبریری: Snowflake کسٹمرز (2024) — رپورٹس کے مطابق MFA کے بغیر چوری شدہ پاس ورڈز سے رسائی؛ Capital One (2019) — misconfiguration اور SSRF۔</p>"},activity:{type:"classify",title:"کلاؤڈ کنفیگریشن آڈٹ",stages:[{name:"Beginner",buckets:["✅ محفوظ","❌ خطرناک"],items:[["Bucket: public-read",1],["Admin پر MFA",0],["Access key GitHub پر",1],["Audit logging آن",0],["سب صارفین AdministratorAccess",1]]},{name:"Advanced",buckets:["فراہم کنندہ کی ذمہ داری","گاہک کی ذمہ داری"],items:[["ڈیٹا سینٹر کی جسمانی حفاظت",0],["Bucket کی رسائی کی سیٹنگ",1],["IAM پالیسیاں",1],["ہارڈویئر کی مرمت",0],["ڈیٹا کی encryption کی سیٹنگ",1]]}]},quiz:[{q:"Shared responsibility میں bucket کی سیٹنگ کس کی ذمہ داری؟",o:["گاہک","فراہم کنندہ"],a:0,e:"Configuration گاہک کی ہے۔"},{q:"Cloud admin اکاؤنٹ پر سب سے اہم؟",o:["MFA","رنگین theme"],a:0,e:"MFA چوری شدہ پاس ورڈ کے اثر کو روکتا ہے۔"}],reflect:"Least privilege کلاؤڈ میں کیسے لاگو ہوتا ہے؟",concepts:[{k:["cloud","کلاؤڈ","aws","azure","bucket","s3","iam"],t:"Cloud security",noori:"Shared responsibility: فراہم کنندہ انفراسٹرکچر، آپ configuration/ڈیٹا/IAM۔ Public buckets سے بچیں، MFA، least privilege IAM، keys کی حفاظت، logging۔"}]},{id:"s15-risk",building:"cyber",order:15,icon:"⚖️",tracks:["noori"],skill:"risk",skillName:"رسک اسیسمنٹ",title:"رسک اسیسمنٹ اور Remediation",en:"Risk Assessment & Remediation",minutes:25,objective:"رسک = امکان × اثر سے ترجیح دینا، اور remediation پلان بنانا۔",lessons:[{t:"رسک میٹرکس",h:"<p>امکان (1–5) × اثر (1–5) = رسک اسکور (1–25)۔ 15+ Critical، 10–14 High، 5–9 Medium، 1–4 Low۔</p><p>ردعمل: <b>Mitigate</b> (کنٹرول لگائیں)، <b>Transfer</b> (انشورنس)، <b>Avoid</b> (کام نہ کریں)، <b>Accept</b> (دستاویز کے ساتھ قبول)۔</p>"}],example:{t:"مثال",h:"<p>انٹرنیٹ پر کھلا RDP: امکان 5، اثر 5 → 25 Critical → فوراً بند کریں، VPN + MFA۔</p>"},activity:{type:"risk",title:"رسک ترجیحی مشق (اصلی حساب)",stages:[{name:"Beginner",items:[["RDP انٹرنیٹ پر کھلا، پاس ورڈ کمزور",5,5],["دفتر کا پرنٹر پرانا firmware",2,2],["Admin بغیر MFA",4,5]]},{name:"Intermediate",items:[["ویب سائٹ میں SQL injection",4,5],["بیک اپ کبھی ٹیسٹ نہیں ہوا",3,4],["لاگنگ بند",3,3],["WiFi guest نیٹ ورک الگ نہیں",3,2]]}]},quiz:[{q:"امکان 4، اثر 3؟",o:["12 High","7 Medium"],a:0,e:"4×3 = 12۔"},{q:"Accept کا مطلب؟",o:["جان بوجھ کر، دستاویز کے ساتھ رسک قبول","نظر انداز کرنا"],a:0,e:"فیصلہ لکھا جاتا ہے۔"}],reflect:"محدود وقت ہو تو پہلے کون سا رسک ٹھیک کریں گی اور کیوں؟",concepts:[{k:["risk","رسک","risk assessment","remediation"],t:"Risk assessment",noori:"رسک = امکان × اثر۔ ترجیح سے mitigate/transfer/avoid/accept کریں؛ remediation پلان میں مالک، تاریخ اور retest۔"}]})}();
